SHOP_NAMES=DATA["shops"]
COHORTS=DATA["cohorts"]
ITEMS=DATA["items"]
def features(obs,p):
    farm=obs['farms'][p];counts=Counter()
    for row in farm['tiles']:
        for tile in row:
            if isinstance(tile,dict):counts[tile.get('crop',tile.get('animal',tile.get('kind')))]+=1
    shops=Counter(obs['town']['unlocked_shops'])
    return ([shops[k]*1.5 for k in SHOP_NAMES]
            +[counts[k]/10 for k in COHORTS]
            +[(obs['market']['inventory'][k]-10000)/rules.MARKET_PARAMS[k]['T'] for k in ITEMS]
            +[len(farm['unlocked_quadrants']),math.log1p(max(0,farm['money']))/3])

def select(obs,p,limit=6):
    day=obs['step']//24;x=features(obs,p)
    rows=sorted((r for r in DATA['rows'] if r['day']==day),key=lambda r:sum((a-b)**2 for a,b in zip(x,r['x'])))[:limit]
    belief=obs.get('_inventory_belief',{})
    if not belief:return rows
    out=[]
    for i,source in enumerate(rows):
        row=copy.deepcopy(source)
        for k,bounds in belief.items():
            index=ITEMS.index(k);prior=source['stock'][k]
            width=bounds['high']-bounds['low']
            estimate=bounds[('low','mean','high')[i%3]]
            # Censored floor sales or possible overflow must not erase an
            # empirically observed holding style. Shrink only by precision.
            weight=1/(1+width/10)
            target=(1-weight)*prior+weight*estimate
            release=source['stock_release'][k]
            total=sum(release)
            if total:
                for t,amount in enumerate(release):row['residual'][index][t]+=(target-prior)*amount/total
            elif target>0:row['residual'][index][0]+=target
        out.append(row)
    return out
